import XCTest

/// The companion's wire format, held to the TypeScript side's own fixtures.
///
/// `vectors.json` was generated by libsodium and is what the tweetnacl client
/// is already tested against, so passing here means the phone and the Mac
/// agree on every byte — not merely that this code agrees with itself.
final class SecretBoxTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Vector: Decodable {
            let key: String
            let nonce: String
            let ct: String
        }
        let vectors: [Vector]
    }

    private static var vectorsURL: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()      // Tests
            .deletingLastPathComponent()      // apple
            .deletingLastPathComponent()      // repo root
            .appendingPathComponent("packages/sync-crypto/test/vectors.json")
    }

    /// The raw JSON payloads, by vector index, in their exact source bytes.
    private func payloads() throws -> [Any] {
        let root = try JSONSerialization.jsonObject(with: Data(contentsOf: Self.vectorsURL), options: [.fragmentsAllowed])
        let vectors = try XCTUnwrap((root as? [String: Any])?["vectors"] as? [[String: Any]])
        return vectors.map { $0["payload"] as Any }
    }

    func testOpensEveryLibsodiumVector() throws {
        let file = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: Self.vectorsURL))
        let expected = try payloads()
        XCTAssertFalse(file.vectors.isEmpty)

        for (i, v) in file.vectors.enumerated() {
            let key = try XCTUnwrap(Base64.decode(v.key))
            let nonce = try XCTUnwrap(Base64.decode(v.nonce))
            let boxed = try XCTUnwrap(Base64.decode(v.ct))

            let plaintext = try SecretBox.open(boxed, nonce: nonce, key: key)
            let decoded = try JSONSerialization.jsonObject(with: Data(plaintext), options: [.fragmentsAllowed])
            XCTAssertEqual(decoded as? NSObject, expected[i] as? NSObject, "vector \(i) decrypted to the wrong payload")
        }
    }

    func testSealReproducesLibsodiumByteForByte() throws {
        let file = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: Self.vectorsURL))
        for (i, v) in file.vectors.enumerated() {
            let key = try XCTUnwrap(Base64.decode(v.key))
            let nonce = try XCTUnwrap(Base64.decode(v.nonce))
            let boxed = try XCTUnwrap(Base64.decode(v.ct))
            let plaintext = try SecretBox.open(boxed, nonce: nonce, key: key)

            XCTAssertEqual(try SecretBox.seal(plaintext, nonce: nonce, key: key), boxed, "vector \(i)")
        }
    }

    func testTamperingAnyByteFailsAuthentication() throws {
        let file = try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: Self.vectorsURL))
        let v = try XCTUnwrap(file.vectors.first)
        let key = try XCTUnwrap(Base64.decode(v.key))
        let nonce = try XCTUnwrap(Base64.decode(v.nonce))
        let boxed = try XCTUnwrap(Base64.decode(v.ct))

        for i in [0, 15, 16, boxed.count - 1] {
            var bad = boxed
            bad[i] ^= 0x01
            XCTAssertThrowsError(try SecretBox.open(bad, nonce: nonce, key: key)) {
                XCTAssertEqual($0 as? SecretBox.Failure, .authentication)
            }
        }
        var wrongKey = key
        wrongKey[0] ^= 0x80
        XCTAssertThrowsError(try SecretBox.open(boxed, nonce: nonce, key: wrongKey))
    }

    func testLongMessagesSpanManyBlocks() throws {
        // Poly1305 partial final blocks and multi-block keystreams, round-tripped
        // at every length around the 16- and 64-byte boundaries.
        let key = (0..<32).map { UInt8($0) }
        let nonce = (0..<24).map { UInt8(100 + $0) }
        for length in [0, 1, 15, 16, 17, 31, 32, 33, 63, 64, 65, 127, 128, 129, 1000] {
            let message = (0..<length).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ 7) }
            let boxed = try SecretBox.seal(message, nonce: nonce, key: key)
            XCTAssertEqual(boxed.count, length + 16)
            XCTAssertEqual(try SecretBox.open(boxed, nonce: nonce, key: key), message, "length \(length)")
        }
    }
}

final class PairingCodeTests: XCTestCase {
    private func code(_ json: String) -> String {
        let b64 = Data(json.utf8).base64EncodedString()
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
        return "budgetr1." + b64
    }

    private let key = "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="

    func testDecodesWhatTheMacEncodes() throws {
        let m = try PairingCode.decode(code(#"{"relayUrl":"https://budgetr-relay.fly.dev","channelId":"ch_1","channelToken":"tok","syncKey":"\#(key)","v":1}"#))
        XCTAssertEqual(m.relayUrl, "https://budgetr-relay.fly.dev")
        XCTAssertEqual(m.channelId, "ch_1")
        XCTAssertEqual(m.channelToken, "tok")
        XCTAssertEqual(m.keyBytes.count, 32)
    }

    func testToleratesSurroundingWhitespace() throws {
        let raw = code(#"{"relayUrl":"https://r.example","channelId":"c","channelToken":"t","syncKey":"\#(key)","v":1}"#)
        XCTAssertNoThrow(try PairingCode.decode("  \(raw)\n"))
    }

    func testRejectsWhatIsntAPairingCode() {
        XCTAssertThrowsError(try PairingCode.decode("https://example.com")) {
            XCTAssertEqual($0 as? PairingCode.Failure, .notAPairingCode)
        }
        XCTAssertThrowsError(try PairingCode.decode("budgetr1.!!!")) {
            XCTAssertEqual($0 as? PairingCode.Failure, .malformed)
        }
    }

    func testRejectsNewerVersionsAndBadFields() {
        XCTAssertThrowsError(try PairingCode.decode(code(#"{"relayUrl":"https://r","channelId":"c","channelToken":"t","syncKey":"\#(key)","v":2}"#))) {
            XCTAssertEqual($0 as? PairingCode.Failure, .unsupportedVersion(2))
        }
        XCTAssertThrowsError(try PairingCode.decode(code(#"{"relayUrl":"ftp://r","channelId":"c","channelToken":"t","syncKey":"\#(key)","v":1}"#))) {
            XCTAssertEqual($0 as? PairingCode.Failure, .badRelayUrl)
        }
        XCTAssertThrowsError(try PairingCode.decode(code(#"{"relayUrl":"https://r","channelId":"c","channelToken":"t","syncKey":"c2hvcnQ=","v":1}"#))) {
            XCTAssertEqual($0 as? PairingCode.Failure, .badKey)
        }
        XCTAssertThrowsError(try PairingCode.decode(code(#"{"relayUrl":"https://r","channelId":"","channelToken":"t","syncKey":"\#(key)","v":1}"#))) {
            XCTAssertEqual($0 as? PairingCode.Failure, .missing("channelId"))
        }
    }
}

final class SummaryContractTests: XCTestCase {
    private let sample = #"""
    {"v":2,"asOf":1760000000,"appliedOpIds":[],
     "netWorth":{"cents":12345600,"spark":[{"d":1759622400,"cents":12000000},{"d":1759708800,"cents":12345600}]},
     "accounts":[{"id":"a1","name":"Checking","kind":"depository","cents":500000},{"id":"a2","name":"Card","kind":"credit","cents":-120000}],
     "budgets":[{"category":"cat_food","spentCents":40000,"limitCents":60000,"state":"warn"}],
     "recent":[{"id":"t1","ts":1759708800,"merchant":"Blue Bottle","cents":-650,"category":"cat_food","pending":false}],
     "positions":[{"symbol":"VTI","cents":500000,"dayBp":-42}],
     "alerts":[],
     "categories":[{"id":"cat_food","name":"Food & Drink","icon":"UtensilsCrossed","group":"spending"}],
     "people":[],"shared":[]}
    """#

    func testDecodesAVersion2Summary() throws {
        let s = try SummaryContract.decode(Data(sample.utf8))
        XCTAssertEqual(s.netWorth.cents, 12_345_600)
        XCTAssertEqual(s.accounts.count, 2)
        XCTAssertEqual(s.budgets.first?.state, "warn")
        XCTAssertEqual(s.positions.first?.dayBp, -42)
        XCTAssertNil(s.investments)
        XCTAssertNil(s.outboxVersion) // a Mac from before the field

        let advertised = sample.replacingOccurrences(of: #""appliedOpIds":[]"#, with: #""appliedOpIds":[],"outboxVersion":3"#)
        XCTAssertEqual(try SummaryContract.decode(Data(advertised.utf8)).outboxVersion, 3)
    }

    func testANewerFormatAsksForAnUpdate() {
        let newer = sample.replacingOccurrences(of: #""v":2"#, with: #""v":3"#)
        XCTAssertThrowsError(try SummaryContract.decode(Data(newer.utf8))) {
            XCTAssertEqual($0 as? SummaryContract.Failure, .updateRequired)
        }
    }

    func testOpensASealedSummaryAndRejectsTheWrongKey() throws {
        let key = (0..<32).map { UInt8($0) }
        let nonce = (0..<24).map { UInt8(200 &+ $0) }
        let boxed = try SecretBox.seal(Array(sample.utf8), nonce: nonce, key: key)
        let envelope = #"{"v":1,"alg":"xsalsa20-poly1305","nonce":"\#(Base64.encode(nonce))","ct":"\#(Base64.encode(boxed))"}"#

        let s = try SummaryContract.open(Data(envelope.utf8), key: key)
        XCTAssertEqual(s.recent.first?.merchant, "Blue Bottle")

        var wrong = key
        wrong[31] ^= 1
        XCTAssertThrowsError(try SummaryContract.open(Data(envelope.utf8), key: wrong)) {
            XCTAssertEqual($0 as? SummaryContract.Failure, .tampered)
        }
    }
}

final class CompanionModelTests: XCTestCase {
    private func day(_ y: Int, _ m: Int, _ d: Int) -> Int {
        Int(CompanionModel.utc.date(from: DateComponents(year: y, month: m, day: d))!.timeIntervalSince1970)
    }

    func testMonthTotalsCompareLikeForLike() {
        let now = CompanionModel.utc.date(from: DateComponents(year: 2026, month: 10, day: 3, hour: 12))!
        let month = CompanionModel.Month(now: now)
        XCTAssertEqual(month.dayOfMonth, 3)
        XCTAssertEqual(month.daysInMonth, 31)

        let points: [Summary.SparkPoint] = [
            .init(d: day(2026, 9, 1), cents: 1000),
            .init(d: day(2026, 9, 2), cents: 1000),
            .init(d: day(2026, 9, 20), cents: 99_999), // past the 3rd: not like-for-like
            .init(d: day(2026, 10, 1), cents: 1500),
            .init(d: day(2026, 10, 3), cents: 1500),
        ]
        let t = CompanionModel.totals(points, month: month)
        XCTAssertEqual(t.spentCents, 3000)
        XCTAssertEqual(t.priorCents, 2000)
        XCTAssertEqual(t.perDay, [1500, 0, 1500])
        XCTAssertEqual(t.cumulative, [1500, 1500, 3000])
        XCTAssertEqual(t.deltaPct ?? 0, 50, accuracy: 0.001)
    }

    func testBudgetedCategoriesUseTheMacsNumbers() throws {
        let json = #"""
        {"v":2,"asOf":0,"appliedOpIds":[],"netWorth":{"cents":0,"spark":[]},"accounts":[],
         "budgets":[{"category":"cat_food","spentCents":40000,"limitCents":60000,"state":"ok"}],
         "recent":[
           {"id":"1","ts":\#(day(2026, 10, 2)),"merchant":"A","cents":-999,"category":"cat_food","pending":false},
           {"id":"2","ts":\#(day(2026, 10, 2)),"merchant":"B","cents":-2500,"category":"cat_fun","pending":false},
           {"id":"3","ts":\#(day(2026, 10, 2)),"merchant":"Pay","cents":400000,"category":"cat_income","pending":false},
           {"id":"4","ts":\#(day(2026, 9, 28)),"merchant":"Old","cents":-5000,"category":"cat_fun","pending":false}],
         "positions":[],"alerts":[],
         "categories":[{"id":"cat_income","name":"Income","group":"income"}]}
        """#
        let s = try SummaryContract.decode(Data(json.utf8))
        let month = CompanionModel.Month(now: CompanionModel.utc.date(from: DateComponents(year: 2026, month: 10, day: 3))!)
        let rows = CompanionModel.categorySpend(s, month: month)

        XCTAssertEqual(rows.map(\.id), ["cat_food", "cat_fun"])
        XCTAssertEqual(rows[0].cents, 40000)       // the Mac's figure, not the tape's 999
        XCTAssertFalse(rows[0].partial)
        XCTAssertEqual(rows[1].cents, 2500)        // last month's row excluded
        XCTAssertTrue(rows[1].partial)
        XCTAssertEqual(rows[1].name, "Fun")        // humanised key
    }
}

// ── What counts as spend, and the outbox wire format ────────────────

final class CompanionFlowTests: XCTestCase {
    private let index: [String: Summary.Category] = [
        "cat_food": .init(id: "cat_food", name: "Food", icon: nil, group: "spending"),
        "cat_loan_payments": .init(id: "cat_loan_payments", name: "Loan Payments", icon: nil, group: "transfer"),
        "cat_transfer_in": .init(id: "cat_transfer_in", name: "Transfer In", icon: nil, group: "transfer"),
        "cat_income": .init(id: "cat_income", name: "Income", icon: nil, group: "income"),
    ]

    private func txn(_ cents: Int, _ cat: String) -> Summary.Txn {
        .init(id: UUID().uuidString, ts: 0, merchant: "m", cents: cents, category: cat, pending: false)
    }

    func testCardPaymentsAndTransfersAreNeitherSpendNorIncome() {
        // "AMERICAN EXPRESS DES:ACH PMT" from checking, and the card's own
        // "AUTOPAY PAYMENT - THANK YOU" credit.
        let amex = txn(-642_116, "cat_loan_payments")
        let autopay = txn(642_116, "cat_loan_payments")
        let venmoIn = txn(6_450, "cat_transfer_in")
        for t in [amex, autopay, venmoIn] {
            XCTAssertEqual(CompanionModel.flow(t, index), .transfer)
            XCTAssertFalse(CompanionModel.isSpend(t, index))
            XCTAssertFalse(CompanionModel.isIncome(t, index))
        }
        XCTAssertTrue(CompanionModel.isSpend(txn(-1_200, "cat_food"), index))
        XCTAssertTrue(CompanionModel.isIncome(txn(400_000, "cat_income"), index))
        // A key the vocabulary hasn't caught up with still reads by its name.
        XCTAssertFalse(CompanionModel.isSpend(txn(-500, "cat_transfer_out_new"), index))
        XCTAssertTrue(CompanionModel.isSpend(txn(-500, "cat_brand_new"), index))
    }

    func testOpsEncodeToTheContractShape() throws {
        let split = CompanionOp.splitBill(.init(
            id: "op1", ts: 10, txnId: "t1",
            shares: [.init(personId: "p1", cents: 6_450)], note: nil
        ))
        let settle = CompanionOp.recordSettlement(.init(id: "op2", ts: 11, personId: "p1", cents: 6_450, txnId: "venmo"))

        let a = try JSONSerialization.jsonObject(with: JSONEncoder().encode(split)) as! [String: Any]
        XCTAssertEqual(a["kind"] as? String, "splitBill")
        XCTAssertEqual(a["txnId"] as? String, "t1")
        XCTAssertNil(a["note"], "absent, not null")
        let shares = a["shares"] as! [[String: Any]]
        XCTAssertEqual(shares.first?["personId"] as? String, "p1")
        XCTAssertEqual(shares.first?["cents"] as? Int, 6_450)

        let b = try JSONSerialization.jsonObject(with: JSONEncoder().encode(settle)) as! [String: Any]
        XCTAssertEqual(Set(b.keys), ["kind", "id", "ts", "personId", "cents", "txnId"])
        XCTAssertEqual(b["kind"] as? String, "recordSettlement")

        // And back, for the on-disk queue.
        XCTAssertEqual(try JSONDecoder().decode(CompanionOp.self, from: JSONEncoder().encode(split)), split)
        XCTAssertEqual(try JSONDecoder().decode(CompanionOp.self, from: JSONEncoder().encode(settle)), settle)
    }

    func testSealedBatchOpensWithTheSameKey() throws {
        let key = [UInt8](repeating: 7, count: 32)
        let batch = OutboxBatch(v: OutboxContract.version, deviceId: "dev_x", batchId: "b1", createdAt: 1, ops: [
            .recordSettlement(.init(id: "op", ts: 1, personId: "p", cents: 100, txnId: nil)),
        ])
        let plain = try JSONEncoder().encode(batch)
        let env = try Envelope.seal(plain, key: key)
        XCTAssertEqual(env.alg, "xsalsa20-poly1305")
        XCTAssertEqual(Base64.decode(env.nonce)?.count, 24)

        let opened = try SecretBox.open(Base64.decode(env.ct)!, nonce: Base64.decode(env.nonce)!, key: key)
        XCTAssertEqual(Data(opened), plain)

        // Fresh nonce every time — reuse would break the cipher.
        XCTAssertNotEqual(try Envelope.seal(plain, key: key).nonce, env.nonce)
    }
}

final class AddPersonOpTests: XCTestCase {
    func testAddPersonEncodesAndPicksTheBatchVersion() throws {
        let add = CompanionOp.addPerson(.init(id: "op", ts: 1, personId: "person_x", name: "Rowan", handle: "@rowan", color: "#6FE3A6"))
        let json = try JSONSerialization.jsonObject(with: JSONEncoder().encode(add)) as! [String: Any]
        XCTAssertEqual(json["kind"] as? String, "addPerson")
        XCTAssertEqual(Set(json.keys), ["kind", "id", "ts", "personId", "name", "handle", "color"])
        XCTAssertEqual(try JSONDecoder().decode(CompanionOp.self, from: JSONEncoder().encode(add)), add)

        let settle = CompanionOp.recordSettlement(.init(id: "s", ts: 1, personId: "p", cents: 1, txnId: nil))
        // Only a batch that needs v3 says v3, so an older Mac keeps applying the rest.
        XCTAssertEqual(OutboxContract.version(for: [settle]), 2)
        XCTAssertEqual(OutboxContract.version(for: [add, settle]), 3)
    }

    func testAnOlderMacGetsEverythingItCanReadAndTheRestWaits() {
        let add = CompanionOp.addPerson(.init(id: "add", ts: 1, personId: "person_new", name: "Rowan", handle: nil, color: nil))
        let splitNew = CompanionOp.splitBill(.init(id: "split-new", ts: 2, txnId: "t1", shares: [.init(personId: "person_new", cents: 500)], note: nil))
        let settleNew = CompanionOp.recordSettlement(.init(id: "settle-new", ts: 3, personId: "person_new", cents: 500, txnId: nil))
        let splitOld = CompanionOp.splitBill(.init(id: "split-old", ts: 4, txnId: "t2", shares: [.init(personId: "p-maya", cents: 700)], note: nil))
        let settleOld = CompanionOp.recordSettlement(.init(id: "settle-old", ts: 5, personId: "p-maya", cents: 700, txnId: nil))
        let queue = [add, splitNew, settleNew, splitOld, settleOld]

        // A Mac that reads v2 only — said so, or too old to say.
        for peer in [2, nil] as [Int?] {
            let gate = OutboxContract.partition(queue, peer: peer)
            XCTAssertEqual(gate.send.map(\.id), ["split-old", "settle-old"])
            XCTAssertEqual(gate.held.map(\.id), ["add", "split-new", "settle-new"])
            // What goes out is a batch that Mac accepts.
            XCTAssertEqual(OutboxContract.version(for: gate.send), 2)
        }

        // An up-to-date Mac takes the lot.
        let gate = OutboxContract.partition(queue, peer: 3)
        XCTAssertEqual(gate.send.map(\.id), queue.map(\.id))
        XCTAssertTrue(gate.held.isEmpty)
    }

    func testItemizedSplitCarriesBasisAndItems() throws {
        let split = CompanionOp.splitBill(.init(id: "op", ts: 1, txnId: "t", shares: [.init(personId: "p", cents: 3934)], note: nil, basisCents: 9000, itemsJson: "{\"v\":1}"))
        let json = try JSONSerialization.jsonObject(with: JSONEncoder().encode(split)) as! [String: Any]
        XCTAssertEqual(json["basisCents"] as? Int, 9000)
        XCTAssertEqual(json["itemsJson"] as? String, "{\"v\":1}")
    }
}
